create table public.alerts(id uuid primary key default gen_random_uuid(),title text not null,message text,type text not null default 'INFO',priority integer not null default 0,active boolean not null default true,start_date timestamptz,end_date timestamptz,created_at timestamptz not null default now());
alter table public.alerts enable row level security;
create policy "active alerts read" on public.alerts for select to authenticated using((active and (start_date is null or start_date<=now()) and (end_date is null or end_date>=now())) or (select private.is_manager()));
create or replace function public.admin_save_alert(p_id uuid,p_title text,p_message text,p_type text,p_priority integer,p_active boolean,p_start_date timestamptz,p_end_date timestamptz) returns uuid language plpgsql security definer set search_path='' as $$ declare v_id uuid; begin if not private.is_manager() then raise exception 'Manager required'; end if; if p_id is null then insert into public.alerts(title,message,type,priority,active,start_date,end_date) values(p_title,p_message,p_type,p_priority,p_active,p_start_date,p_end_date) returning id into v_id; else update public.alerts set title=p_title,message=p_message,type=p_type,priority=p_priority,active=p_active,start_date=p_start_date,end_date=p_end_date where id=p_id returning id into v_id; end if; return v_id; end; $$;
create or replace function public.admin_delete_alert(p_id uuid) returns void language plpgsql security definer set search_path='' as $$ begin if not private.is_manager() then raise exception 'Manager required'; end if; delete from public.alerts where id=p_id; end; $$;
revoke all on function public.admin_save_alert(uuid,text,text,text,integer,boolean,timestamptz,timestamptz),public.admin_delete_alert(uuid) from public,anon; grant execute on function public.admin_save_alert(uuid,text,text,text,integer,boolean,timestamptz,timestamptz),public.admin_delete_alert(uuid) to authenticated; grant select on public.alerts to authenticated;
